function initState() {
    return {
        power: false,
        vacuum: false,
        rf: false,
        magnet: true,
        interlocks: false, // Wajib ON Manual
        beam: false,
        paused: false,
        emergency: false,
        exposureActive: false,
        basePressure: 1013.0, // Mulai dari 1 atm
        baseRf: 0.0,
        baseCurrent: 0.0,
        baseEnergy: 0.0,
        magnetCurrent: 1450,
        frequency: 22.50,
        rfPower: 0.0,
        cavityTemp: 54.3,
        pressure: 1013.0,
        magnetPower: 85.2,
        targetCurrent: 0.0,
        beamCurrent: 0.0,
        beamEnergy: 0.0,
        peakEnergy: 13.0,
        exposureSeconds: 0,
        exposureStartedAt: null,
        lastTickMs: Date.now(),
        pressureHistory: [1013, 1013, 1013, 1013, 1013],
        targetHistory: [0, 0, 0, 0, 0],
        beamCurrentHistory: [0, 0, 0, 0, 0],
        logs: [],
        mode: "Standby"
    };
}
function log(state, text) {
    const t = new Date().toLocaleTimeString('id-ID', {hour12:false});
    state.logs.unshift(t + ' - ' + text);
    state.logs = state.logs.slice(0, 12);
}
function jitter(value, percent) {
    return value + ((Math.random() - 0.5) * value * percent);
}
function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
}

let state = global.get('cyclotron');
if (!state) {
    state = initState();
    log(state, 'Sistem dinyalakan. Menunggu Power & Vacuum.');
    global.set('cyclotron', state);
}

// Kalkulasi Delta Time (dt) untuk Fisika Animasi
let nowMs = Date.now();
let dt = (nowMs - state.lastTickMs) / 1000.0;
if (dt > 2.0 || dt < 0) dt = 0.25; // Clamp jika terjadi lag ekstrim
state.lastTickMs = nowMs;

// 1. PHYSICS: Vacuum Pressure (Naik turun dalam 5 detik)
let pTarget = state.vacuum ? 1.2e-7 : 1013.0;
let pRate = 1013.0 / 5.0; // Pergerakan per detik
if (state.basePressure < pTarget) state.basePressure = Math.min(state.basePressure + pRate * dt, pTarget);
if (state.basePressure > pTarget) state.basePressure = Math.max(state.basePressure - pRate * dt, pTarget);

// 2. PHYSICS: RF Power (Naik 5s, Turun 5s)
let rfTarget = state.beam ? 185.7 : 0.0;
let rfRate = 185.7 / 5.0;
if (state.baseRf < rfTarget) state.baseRf = Math.min(state.baseRf + rfRate * dt, rfTarget);
if (state.baseRf > rfTarget) state.baseRf = Math.max(state.baseRf - rfRate * dt, rfTarget);

// 3. PHYSICS: Beam Current (Naik 3s, Turun 3s)
let curTarget = state.beam ? 8.4 : 0.0;
let curRate = 8.4 / 3.0;
if (state.baseCurrent < curTarget) state.baseCurrent = Math.min(state.baseCurrent + curRate * dt, curTarget);
if (state.baseCurrent > curTarget) state.baseCurrent = Math.max(state.baseCurrent - curRate * dt, curTarget);

// 4. PHYSICS: Beam Energy (Naik 8s, Turun 3s)
let enTarget = state.beam ? 13.0 : 0.0;
let enRateRise = 13.0 / 8.0;
let enRateFall = 13.0 / 3.0;
if (state.baseEnergy < enTarget) state.baseEnergy = Math.min(state.baseEnergy + enRateRise * dt, enTarget);
if (state.baseEnergy > enTarget) state.baseEnergy = Math.max(state.baseEnergy - enRateFall * dt, enTarget);

// Terapkan Jitter HANYA ketika nilai sudah stabil
state.pressure = (Math.abs(state.basePressure - 1.2e-7) < 1e-6) ? jitter(1.2e-7, 0.35) : state.basePressure;
state.rfPower = (state.baseRf === 185.7) ? jitter(185.7, 0.025) : state.baseRf;
state.beamCurrent = (state.baseCurrent === 8.4) ? clamp(jitter(8.4, 0.45), 0, 12.0) : state.baseCurrent;
state.beamEnergy = (state.baseEnergy === 13.0) ? clamp(jitter(12.95, 0.008), 0, 13.0) : state.baseEnergy;
state.targetCurrent = state.beam ? clamp(jitter(state.beamCurrent, 0.25), 0, 12.0) : state.baseCurrent;

// Cascading Safety (Interlock drop jika power/vac mati)
if (!state.power || !state.vacuum) {
    if (state.interlocks) log(state, 'CAUTION: Interlock terputus karena Vacuum/Power mati!');
    state.interlocks = false;
}
// Beam otomatis mati jika interlock lepas
if (!state.interlocks && state.beam) {
    state.beam = false;
    log(state, 'BEAM DROP: Safety Interlock terbuka!');
}

// Update Mode & State RF HMI
if (state.beam || state.baseRf > 0) {
    state.rf = true;
    if (state.beam) {
        state.mode = state.exposureActive ? "Exposure Active" : "Beam On";
        if (state.exposureActive) state.exposureSeconds += dt;
    } else {
        state.mode = "Cooling Down"; // Sedang proses turun bertahap
    }
    state.magnetCurrent = jitter(1450, 0.015);
    state.frequency = jitter(22.50, 0.001);
    state.cavityTemp = jitter(54.3, 0.02);
    state.magnetPower = jitter(85.2, 0.05);
} else {
    state.mode = "Standby";
    state.rf = false;
    state.exposureActive = false;
}

// Catat ke Grafik (Setiap beberapa waktu)
if (Math.random() < 0.3) { // Karena refresh cepat, kita kurangi sample rate ke grafik
    state.pressureHistory.push(Number(state.pressure));
    state.targetHistory.push(Number(state.targetCurrent));
    state.beamCurrentHistory.push(Number(state.beamCurrent));
    state.pressureHistory = state.pressureHistory.slice(-30);
    state.targetHistory = state.targetHistory.slice(-30);
    state.beamCurrentHistory = state.beamCurrentHistory.slice(-30);
}
global.set('cyclotron', state);

msg.payload = {
    time: new Date().toLocaleTimeString('id-ID', {hour12:false}),
    mode: state.mode,
    status: {
        power: Boolean(state.power),
        vacuum: Boolean(state.vacuum),
        rf: Boolean(state.rf),
        magnet: Boolean(state.magnet),
        interlocks: Boolean(state.interlocks),
        beam: Boolean(state.beam),
        paused: Boolean(state.paused),
        emergency: Boolean(state.emergency),
        exposureActive: Boolean(state.exposureActive)
    },
    metrics: {
        magnetCurrent: Number(state.magnetCurrent),
        frequency: Number(state.frequency),
        rfPower: Number(state.rfPower),
        cavityTemp: Number(state.cavityTemp),
        pressure: Number(state.pressure),
        magnetPower: Number(state.magnetPower),
        targetCurrent: Number(state.targetCurrent),
        beamCurrent: Number(state.beamCurrent),
        beamEnergy: Number(state.beamEnergy),
        peakEnergy: Number(state.peakEnergy),
        exposureSeconds: Number(state.exposureSeconds)
    },
    history: {
        pressure: state.pressureHistory,
        target: state.targetHistory,
        beamCurrent: state.beamCurrentHistory
    },
    logs: state.logs
};
msg.headers = {"content-type":"application/json"};
return msg;

function log(state, text) {
    const t = new Date().toLocaleTimeString('id-ID', {hour12:false});
    state.logs.unshift(t + ' - ' + text);
    state.logs = state.logs.slice(0, 12);
}

let state = global.get('cyclotron');
if (!state) return [null, null];

let body = msg.payload || (msg.req && msg.req.body) || {};
if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch(e) { body = {}; }
}
let cmd = String(body.cmd || '').toUpperCase();
let hwCmdStr = 'IGNORE_HARDWARE'; // Aman dari trigger palsu

switch (cmd) {
    case 'TOGGLE_POWER':
        state.power = !state.power;
        log(state, 'Sistem Power ' + (state.power ? 'ON (Buzzer 5s)' : 'OFF'));
        if (state.power) hwCmdStr = 'POWER_ON';
        break;

    case 'TOGGLE_VACUUM':
        state.vacuum = !state.vacuum;
        log(state, 'Sistem Vacuum ' + (state.vacuum ? 'ON (Relay Kipas Aktif/LOW)' : 'OFF (Relay Mati/HIGH)'));
        hwCmdStr = 'VACUUM_STATE_UPDATE'; // Update pin relay
        break;

    case 'TOGGLE_INTERLOCK':
        if (state.power && state.vacuum) {
            state.interlocks = !state.interlocks;
            log(state, 'Interlock ' + (state.interlocks ? 'SET (Ready)' : 'DIBUKA (Cleared)'));
        } else {
            log(state, 'Interlock GAGAL: Power & Vacuum harus ON!');
        }
        break;

    case 'START_BEAM':
        if (state.interlocks && state.vacuum && state.power) {
            state.emergency = false;
            state.beam = true;
            state.paused = false;
            state.exposureActive = false; 
            log(state, 'Beam On initiated (Energy mendaki pelan)');
            hwCmdStr = 'START_BEAM';
        } else {
            log(state, 'START ditolak: Interlock belum SET!');
        }
        break;

    case 'SHOOT':
        if (state.beam) {
            state.exposureActive = true;
            state.lastTickMs = Date.now();
            if (!state.exposureStartedAt) state.exposureStartedAt = new Date().toISOString();
            log(state, 'Shoot / Exposure Triggered to Hardware');
            hwCmdStr = 'SHOOT';
        } else {
            log(state, 'SHOOT rejected: Beam is not active');
        }
        break;

    case 'EMERGENCY_STOP':
        state.emergency = true; 
        state.power = false;
        state.vacuum = false;
        state.interlocks = false;
        state.beam = false;
        state.exposureActive = false;
        log(state, 'Emergency Stop! Seluruh sistem dimatikan.');
        hwCmdStr = 'EMERGENCY_STOP';
        break;

    case 'AUTO_RESET':
        state.emergency = false;
        state.beam = false;
        state.exposureActive = false;
        // Power, Vacuum, Interlock tetap ON
        log(state, 'Exposure complete. Auto-reset ke Standby (Energi merosot).');
        hwCmdStr = 'AUTO_RESET';
        break;

    case 'SET_PARAMS':
        if (body.magnet_a !== undefined) state.setpointMagnetA = Number(body.magnet_a);
        if (body.rf_mhz !== undefined) state.setpointFreqMhz = Number(body.rf_mhz);
        if (body.rf_kv !== undefined) state.setpointRfKv = Number(body.rf_kv);
        if (body.beam_ua !== undefined) state.setpointBeamUa = Number(body.beam_ua);
        log(state, 'Parameter HMI diperbarui via MQTT/API');
        break;
    default:
        log(state, 'Unknown command: ' + cmd);
}

global.set('cyclotron', state);

// Payload Balasan ke Web Dashboard
msg.payload = { ok: true, command: cmd, mode: state.mode };
msg.headers = {"content-type":"application/json"};

// Payload Perintah Fisik ke Hardware
let hwCommand = {
    payload: {
        cmd: hwCmdStr,
        vac_pin: state.vacuum ? 0 : 1 // Logic Active Low untuk Vacuum Relay
    }
};

return [msg, hwCommand];

let state = global.get('cyclotron') || {};
let data = msg.payload || (msg.req && msg.req.body) || {};
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch(e) { data = {}; }
}

const keys = [
    'power','vacuum','rf','magnet','interlocks','beam','paused','emergency','exposureActive',
    'magnetCurrent','frequency','rfPower','cavityTemp','pressure','magnetPower',
    'targetCurrent','beamCurrent','beamEnergy','peakEnergy','exposureSeconds'
];
keys.forEach(k => {
    if (data[k] !== undefined) state[k] = data[k];
});

global.set('cyclotron', state);
msg.payload = { status: "success", message: "Sensor data updated via LAN", data_received: data };
return msg;
